Boolean dei_sc_icon_smart_mode_on( void )
{                                                                                
    dei_sc_info_set( DEI_SC_INFO_SMART_MODE , TRUE );        
	dei_sc_info_set( DEI_SC_INFO_TIMER_MODE , FALSE);        
    
	if( DEI_SC_PAGGING() ) 
    {
   		dei_sc_automatic_page_update() ;

		return TRUE;
    }
    
	return dei_sc_tx( DEI_SC_ACK_SMART_START_ON , DEI_SC_NORMAL_TX, 100 ) ; 

}

